.neo-section,.neo-numbers,.neo-cta-section{position:relative;isolation:isolate;overflow:hidden;}
.neo-section>.container,.neo-numbers>.container,.neo-cta-section>.container{position:relative;z-index:2;}
.neo-veggie-field{position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:1;perspective:900px;}
.neo-veggie-field span{position:absolute;display:block;font-size:clamp(3.8rem,7vw,6.8rem);line-height:1;opacity:.96;filter:drop-shadow(0 18px 13px rgba(15,45,20,.32));transform-style:preserve-3d;will-change:transform;animation:veggieFlight var(--duration,13s) ease-in-out infinite;animation-delay:var(--delay,0s);user-select:none;}
.neo-veggie-field span:nth-child(1){top:8%;left:4%;--duration:10s;--delay:-3s}
.neo-veggie-field span:nth-child(2){top:57%;left:15%;--duration:12s;--delay:-8s;font-size:clamp(3.2rem,6vw,5.6rem)}
